use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let text = input.as_str().unwrap();
    let shift = input.as_i64().unwrap();
    let mut result = String::new();
    for c in text.chars() {
        if c.is_lowercase() {
            let base = c.to_lowercase().next().unwrap();
            let new_char = (base as u8 - base as u8 + shift as u8) % 26 as u8 + base as u8;
            result.push(new_char as char);
        } else {
            result.push(c);
        }
    }
    Value::String(result)
}
